constraints:
1 ≤ N ≤ 10^{5}
1 ≤ Each element of the list ≤ 10^{5}

expected time complexity: O(N)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def divide(self, N, head):
		odd = None
		even = None
		o = None
		e = None
		curr = head
		while curr != None:
			if curr.data % 2 != 0:
				if odd == None:
					odd = curr
					o = curr
				else:
					o.next = curr
					o = o.next
			elif even == None:
				even = curr
				e = curr
			else:
				e.next = curr
				e = e.next
			curr = curr.next
		if odd == None:
			return even
		if even == None:
			return odd
		else:
			e.next = odd
			o.next = None
			return even
